INSERT INTO public.catalog_sources (id, title, authority, country_code, url, version, licence, recorded_on, status, notes) VALUES
  ('unesco-isced-2011', 'International Standard Classification of Education (ISCED 2011)', 'UNESCO Institute for Statistics', NULL, 'https://uis.unesco.org/en/topic/international-standard-classification-education-isced', 'ISCED 2011', 'Classificação pública da UNESCO; citar a fonte.', '2026-10-10'::date, 'official_verified', NULL),
