  ('ao-lbsee', 'Lei de Bases do Sistema de Educação e Ensino', 'República de Angola — Ministério da Educação', 'AO', NULL, 'Lei n.º 17/16, alterada pela Lei n.º 32/20', 'Diploma legal publicado em Diário da República.', '2026-10-10'::date, 'in_review', 'Etapas e classes escritas a partir da lei; conferir com o texto consolidado.'),
  ('ao-inide-planos', 'Planos curriculares do ensino geral e técnico-profissional', 'INIDE / Ministério da Educação de Angola', 'AO', NULL, 'Planos em vigor (forma mais comum usada pelas escolas)', 'Documentos oficiais; reproduzir só a estrutura (disciplinas por classe).', '2026-10-10'::date, 'in_review', 'Mesma lista já usada pelos modelos de estrutura do SIGA (curriculum-templates.ts). Cargas horárias não incluídas: variam por plano.'),
  ('mz-lei-sne', 'Lei do Sistema Nacional de Educação', 'República de Moçambique — Ministério da Educação e Desenvolvimento Humano', 'MZ', NULL, 'Lei n.º 18/2018', 'Diploma legal publicado no Boletim da República.', '2026-10-10'::date, 'in_review', 'Só etapas e classes. Disciplinas por classe por importar (INDE): sem fonte conferida.'),
  ('pt-dge-curriculo', 'Currículo Nacional — matrizes curriculares do ensino básico e secundário', 'Direção-Geral da Educação (DGE)', 'PT', 'https://www.dge.mec.pt/curriculo-nacional', 'Decreto-Lei n.º 55/2018', 'Informação pública do Ministério da Educação.', '2026-10-10'::date, 'in_review', 'Componentes do currículo por ciclo. Opções do 12.º ano e cursos profissionais por importar.'),
  ('pt-dges-graus', 'Graus e diplomas do ensino superior', 'Direção-Geral do Ensino Superior (DGES)', 'PT', 'https://www.dges.gov.pt', 'Decreto-Lei n.º 74/2006 (republicado)', 'Informação pública.', '2026-10-10'::date, 'in_review', NULL),
  ('siga-catalogo', 'Catálogo de referência SIGA Plus', 'SIGA Plus', NULL, NULL, '2026.10', 'Interno.', '2026-10-10'::date, 'institutional_approved', 'Nomes canónicos, abreviaturas e sinónimos de disciplinas e cursos genéricos. Não diz que um curso é oficial num país nem que uma escola o pode oferecer.')
